const GR20=window.GR20_CONTENT||{campaigns:{},categories:{},trust:[],crossSell:{},trustFaq:[]}; const SITE=window.GR_SITE_CONFIG||{};
const P=DATA.products||[], C=DATA.categories||{};
const qs=(s,c=document)=>c.querySelector(s), qsa=(s,c=document)=>[...c.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const params=new URLSearchParams(location.search); const lang=params.get('lang')==='en'?'en':'ar', isAR=lang==='ar';
document.documentElement.lang=lang; document.documentElement.dir=isAR?'rtl':'ltr'; document.body.dir=document.documentElement.dir;
