const get=(k,d)=>{try{const v=localStorage.getItem(k);return v===null?d:JSON.parse(v)}catch{return d}}, set=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
const K={cart:'gr20_cart',wish:'gr20_wish',compare:'gr20_compare',lists:'gr20_lists',recent:'gr20_recent',orders:'gr20_orders',addresses:'gr20_addresses',coupon:'gr20_coupon',searches:'gr20_searches',draft:'gr20_checkout_draft',savedCart:'gr20_saved_cart',forms:'gr20_forms',version:'gr20_state_version'};
const LEGACY={cart:'gr19_cart',wish:'gr19_wish',compare:'gr19_compare',lists:'gr19_lists',recent:'gr19_recent',orders:'gr19_orders',addresses:'gr19_addresses',coupon:'gr19_coupon',searches:'gr19_searches',draft:'gr19_checkout_draft',savedCart:'gr19_saved_cart',forms:'gr19_forms'};
function migrateState(){if(localStorage.getItem(K.version)==='20')return;Object.keys(LEGACY).forEach(k=>{if(localStorage.getItem(K[k])===null&&localStorage.getItem(LEGACY[k])!==null)localStorage.setItem(K[k],localStorage.getItem(LEGACY[k]))});localStorage.setItem(K.version,'20')}
