let cart=get(K.cart,[]),wish=get(K.wish,[]),compare=get(K.compare,[]),lists=get(K.lists,{}),recent=get(K.recent,[]),orders=get(K.orders,[]),coupon=get(K.coupon,'');
const product=id=>P.find(x=>x.id===id), category=id=>C[id];
const clamp=(n,min,max)=>Math.min(max,Math.max(min,Number.isFinite(+n)?+n:min));
function sanitizeState(){const validId=id=>!!product(id);const merged=new Map();(Array.isArray(cart)?cart:[]).forEach(l=>{const p=product(l?.id);if(!p||p.stock<=0)return;const vi=clamp(Math.floor(+l.variantIndex||0),0,Math.max(0,(p.variants?.length||1)-1));const key=p.id+'::'+vi,prev=merged.get(key)||0;merged.set(key,Math.min(p.stock,prev+clamp(Math.floor(+l.qty||1),1,p.stock)))});cart=[...merged.entries()].map(([key,qty])=>{const [id,vi]=key.split('::');return{id,qty,variantIndex:+vi}});wish=[...new Set(Array.isArray(wish)?wish:[])].filter(validId);compare=[...new Set(Array.isArray(compare)?compare:[])].filter(validId).slice(0,4);recent=[...new Set(Array.isArray(recent)?recent:[])].filter(validId).slice(0,12);const cleanLists={};if(lists&&typeof lists==='object'&&!Array.isArray(lists))Object.entries(lists).slice(0,30).forEach(([name,ids])=>{const n=String(name).trim().slice(0,60);if(n)cleanLists[n]=[...new Set(Array.isArray(ids)?ids:[])].filter(validId).slice(0,100)});lists=cleanLists;orders=Array.isArray(orders)?orders.filter(o=>o&&o.id&&Array.isArray(o.items)).slice(0,20):[];coupon=typeof coupon==='string'?coupon.slice(0,40):'';set(K.cart,cart);set(K.wish,wish);set(K.compare,compare);set(K.recent,recent);set(K.lists,lists);set(K.orders,orders);set(K.coupon,coupon)}
sanitizeState();
function norm(s=''){return String(s).toLowerCase().normalize('NFD').replace(/[\u064b-\u065f\u0670]/g,'').replace(/[أإآ]/g,'ا').replace(/ى/g,'ي').replace(/ؤ/g,'و').replace(/ئ/g,'ي').replace(/ة/g,'ه').replace(/[^\p{L}\p{N}]+/gu,' ').trim()}
const SYN=[['سماد','اسمده','مغذيات','npk','fertilizer','fertilizers'],['بذور','تقاوي','seed','seeds'],['مبيد','مبيدات','pesticide','pesticides','حمايه'],['ري','تنقيط','irrigation','drip'],['ادوات','معدات','tools','equipment'],['بيت محمي','بيوت محميه','greenhouse','greenhouses'],['خيار','cucumber'],['طماطم','tomato'],['فلفل','pepper'],['حديد','iron'],['زنك','zinc']];
function expandedTerms(q){const base=norm(q);const out=new Set(base.split(/\s+/).filter(Boolean));SYN.forEach(g=>{if(g.some(x=>base.includes(norm(x))))g.forEach(x=>out.add(norm(x)))});return [...out]}
function score(p,q){if(!q.trim())return 1;const terms=expandedTerms(q);const hay=norm([p.ar,p.en,p.sku,p.brand,p.type_ar,p.type_en,(p.keywords||[]).join(' '),category(p.cat)?.ar,category(p.cat)?.en].join(' '));let s=0;const nq=norm(q);if(norm(p.sku)===nq)s+=100;if(norm(p.ar)===nq||norm(p.en)===nq)s+=70;if(norm(p.ar).includes(nq)||norm(p.en).includes(nq))s+=35;terms.forEach(x=>{if(hay.includes(x))s+=8});return s}
function searchProducts(q){return P.map(p=>[p,score(p,q)]).filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]||a[0].price-b[0].price).map(x=>x[0])}
function icon(name){const m={menu:'M4 7h16M4 12h16M4 17h16',cart:'M6 8h12l1 12H5L6 8ZM9 8a3 3 0 0 1 6 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.6l-1-1a5.5 5.5 0 0 0-7.8 7.8l1 1L12 21l7.8-7.6 1-1a5.5 5.5 0 0 0 0-7.8Z',home:'M3 11l9-8 9 8M5 10v10h14V10M9 20v-6h6v6',grid:'M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h6v6h-6z',x:'M6 6l12 12M18 6L6 18'};if(name==='search')return '<svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="6"></circle><path d="M16 16l4 4"></path></svg>';if(name==='user')return '<svg viewBox="0 0 24 24"><circle cx="12" cy="8" r="4"></circle><path d="M4 21a8 8 0 0 1 16 0"></path></svg>';return `<svg viewBox="0 0 24 24"><path d="${m[name]||''}"></path></svg>`}
function catName(k){const c=category(k);return c?t(c.ar,c.en):k} function subName(cat,sub){const v=C[cat]?.subs?.[sub];return v?t(v[0],v[1]):sub}
function variantInfo(p,vi=0){const v=p?.variants?.[vi]||p?.variants?.[0];return {label:v?t(v[0],v[1]):'',price:v?v[2]:p?.price||0}}
function lineData(l){const p=product(l.id);if(!p)return null;const v=variantInfo(p,l.variantIndex||0);return {...l,p,v,price:v.price}}
function subtotal(){return cart.reduce((s,l)=>{const d=lineData(l);return s+(d?d.price*(l.qty||1):0)},0)}
function discount(){return coupon==='WELCOME10'?Math.round(subtotal()*.10):0} function total(){return Math.max(0,subtotal()-discount())}
function saveCart(){set(K.cart,cart);updateCounts();renderDrawers()}
function addCart(id,qty=1,variantIndex=0){const p=product(id);if(!p||p.stock<=0){toast(t('المنتج غير متوفر حاليًا','Product is currently unavailable'));return false}variantIndex=clamp(Math.floor(+variantIndex||0),0,Math.max(0,(p.variants?.length||1)-1));qty=clamp(Math.floor(+qty||1),1,p.stock);let l=cart.find(x=>x.id===id&&(x.variantIndex||0)===variantIndex),current=l?.qty||0;if(current>=p.stock){toast(t('وصلت للكمية المتاحة من المنتج','You reached the available stock'));return false}const next=Math.min(p.stock,current+qty);if(l)l.qty=next;else cart.push({id,qty:next,variantIndex});saveCart();toast(next<current+qty?t('تمت الإضافة حتى حد المخزون المتاح','Added up to available stock'):t('تمت الإضافة إلى السلة','Added to cart'));return true}
function toggleWish(id){wish=wish.includes(id)?wish.filter(x=>x!==id):[id,...wish];set(K.wish,wish);updateCounts();renderDrawers();refreshActionStates();toast(wish.includes(id)?t('تم الحفظ في المفضلة','Saved to wishlist'):t('تمت الإزالة من المفضلة','Removed from wishlist'))}
