function productCard(p){const v=variantInfo(p),sale=p.old&&p.old>v.price?Math.round((1-v.price/p.old)*100):0;return `<article class="gr16-card gr18-card" data-product-card="${p.id}"><div class="gr16-card-media gr18-card-media"><a href="${url('product.html',{id:p.id})}" aria-label="${esc(p[isAR?'ar':'en'])}"><img src="${p.img}" loading="lazy" alt="${esc(p[isAR?'ar':'en'])}" width="520" height="520"></a>${sale?`<span class="gr16-badge">−${sale}%</span>`:p.badge_ar?`<span class="gr16-badge">${esc(t(p.badge_ar,p.badge_en||p.badge_ar))}</span>`:''}<div class="gr16-card-actions gr18-card-actions"><button data-wish="${p.id}" aria-label="${wish.includes(p.id)?t('إزالة من المفضلة','Remove from wishlist'):t('إضافة للمفضلة','Add to wishlist')}" aria-pressed="${wish.includes(p.id)}">${icon('heart')}</button><button data-compare="${p.id}" aria-label="${compare.includes(p.id)?t('إزالة من المقارنة','Remove from compare'):t('إضافة للمقارنة','Add to compare')}" aria-pressed="${compare.includes(p.id)}">⇄</button></div><a class="gr18-card-view" href="${url('product.html',{id:p.id})}">${t('عرض المنتج','View product')}</a></div><div class="gr16-card-body gr18-card-body"><div class="gr18-card-topline"><span>${esc(p.brand)}</span><span class="gr18-stock-dot ${p.stock<=0?'sold':p.stock<10?'low':''}">${p.stock<=0?t('غير متوفر','Out of stock'):p.stock<10?t('كمية محدودة','Low stock'):t('متوفر','In stock')}</span></div><span class="gr16-card-type">${esc(t(p.type_ar,p.type_en))}</span><h3><a href="${url('product.html',{id:p.id})}">${esc(p[isAR?'ar':'en'])}</a></h3><div class="gr16-price"><strong>${money(v.price)}</strong>${p.old?`<del>${money(p.old)}</del>`:''}</div><div class="gr20-card-commercial"><small>${esc(p.sku)}</small><button class="gr20-save" data-wish="${p.id}">${wish.includes(p.id)?t('محفوظ','Saved'):t('حفظ','Save')}</button></div><button class="gr16-btn ${p.stock>0?'gr16-btn--primary':'gr16-btn--outline'} gr18-add" data-add="${p.id}" ${p.stock<=0?'disabled':''}>${p.stock>0?t('أضف للسلة','Add to cart'):t('غير متوفر','Unavailable')}</button></div></article>`}
function pageHero(kicker,title,copy=''){return `<section class="gr16-pagehero gr18-pagehero"><div class="gr18-pagehero-mark">ROOTS</div><div class="gr16-container"><span class="gr16-kicker">${esc(kicker)}</span><h1>${title}</h1>${copy?`<p>${copy}</p>`:''}</div></section>`}
function grid(rows){return `<div class="gr16-product-grid">${rows.map(productCard).join('')}</div>`}
function renderDrawers(){const cb=qs('[data-cart-drawer-body]'),wb=qs('[data-wish-drawer-body]');if(cb){const valid=cart.map(lineData).filter(Boolean);cb.innerHTML=valid.length?valid.map((d,i)=>`<div class="gr16-cart-line" data-line="${i}"><img src="${d.p.img}" alt=""><div><strong>${esc(d.p[isAR?'ar':'en'])}</strong><small>${esc(d.v.label)}</small><div class="gr16-line-actions"><button data-dec aria-label="${t('تقليل الكمية','Decrease quantity')}">−</button><span>${d.qty}</span><button data-inc aria-label="${t('زيادة الكمية','Increase quantity')}">+</button><button class="gr16-linkbtn" data-remove>${t('حذف','Remove')}</button></div></div><b>${money(d.price*d.qty)}</b></div>`).join(''):`<div class="gr16-empty"><strong>${t('السلة فارغة','Your cart is empty')}</strong><a href="${url('collection.html')}">${t('ابدأ التسوق','Start shopping')}</a></div>`;qs('[data-cart-total]').textContent=money(total())}if(wb){const rows=wish.map(product).filter(Boolean);wb.innerHTML=rows.length?rows.map(p=>`<div class="gr16-cart-line"><img src="${p.img}" alt=""><div><a href="${url('product.html',{id:p.id})}"><strong>${esc(p[isAR?'ar':'en'])}</strong></a><small>${money(p.price)}</small></div><button class="gr16-linkbtn" data-wish="${p.id}">${t('إزالة','Remove')}</button></div>`).join(''):`<div class="gr16-empty"><strong>${t('لا توجد منتجات محفوظة','No saved products')}</strong></div>`}}
function home(){const featured=P.filter(p=>p.stock>0).slice(0,8),sale=P.filter(p=>p.old&&p.old>p.price&&p.stock>0).slice(0,4),recentRows=recent.map(product).filter(Boolean).slice(0,4),campaigns=Object.entries(GR20.campaigns||{}).slice(0,3);return `<section class="gr16-container"><div class="gr20-commercial-hero"><div class="gr20-commercial-copy"><span class="gr16-kicker">GOLDEN ROOTS · UAE</span><h1>${t('مستلزمات زراعية بترتيب يخلي القرار أسهل.','Agricultural supplies, structured to make selection easier.')}</h1><p>${t('من البذور والتغذية إلى الحماية والري والأدوات — تجربة تجارية واحدة مرتبة للأفراد والمزارع والشركات.','From seeds and nutrition to protection, irrigation and tools — one commercial experience for individuals, farms and businesses.')}</p><div class="gr20-commercial-actions"><a class="gr16-btn gr16-btn--gold" href="${url('collection.html')}">${t('تصفح المنتجات','Browse products')}</a><a class="gr16-btn gr18-dark-outline" href="${url('offers.html')}">${t('شوف العروض','View offers')}</a></div></div><div class="gr20-commercial-media"><img src="assets/golden-roots-hero.webp" alt="${t('جولدن روتس للزراعة ومستلزماتها','Golden Roots Agriculture & Supplies')}"></div></div><div class="gr20-brand-proof">${(GR20.trust||[]).slice(0,4).map(x=>`<div><b>${esc(t(x.ar,x.en))}</b><span>${esc(t(x.copy_ar,x.copy_en))}</span></div>`).join('')}</div></section><section class="gr16-section"><div class="gr16-container"><div class="gr16-head gr18-head"><div><span class="gr16-kicker">COMMERCIAL PATHS</span><h2>${t('ادخل من الطريق الأقرب لاحتياجك','Enter through the path closest to your need')}</h2><p>${t('منتجات، عروض، أو طلب كميات — كل مسار له صفحة واضحة بدل ما كل شيء يبقى في مكان واحد.','Products, offers or volume ordering — each path has a clear destination instead of crowding everything together.')}</p></div></div><div class="gr20-campaign-grid">${campaigns.map(([id,c])=>`<article class="gr20-campaign-card"><div><small>${esc(c.kicker||'GOLDEN ROOTS')}</small><h3>${esc(t(c.ar,c.en))}</h3><p>${esc(t(c.copy_ar,c.copy_en))}</p></div><a href="${url(c.target||'campaign.html',{campaign:id})}">${t('استكشف المسار','Explore path')} →</a></article>`).join('')}</div></div></section><section class="gr16-section gr18-category-story"><div class="gr16-container"><div class="gr16-head gr18-head"><div><span class="gr16-kicker">SHOP BY CATEGORY</span><h2>${t('الكتالوج متقسم عشان توصل أسرع','A catalog divided for faster discovery')}</h2></div><a href="${url('collections.html')}">${t('كل الأقسام','All categories')} →</a></div><div class="gr18-category-mosaic">${Object.entries(C).map(([k,c],i)=>`<a class="gr18-category-tile tile-${i+1}" href="${url('collection.html',{cat:k})}"><img src="${c.img}" loading="lazy" alt="${esc(t(c.ar,c.en))}"><div><span>0${i+1}</span><h3>${esc(t(c.ar,c.en))}</h3><p>${Object.keys(c.subs||{}).length} ${t('تصنيفات فرعية','subcategories')}</p></div></a>`).join('')}</div></div></section><section class="gr16-section"><div class="gr16-container"><div class="gr16-head gr18-head"><div><span class="gr16-kicker">FEATURED PRODUCTS</span><h2>${t('منتجات مختارة من الكتالوج','Selected products from the catalog')}</h2><p>${t('بطاقات أبسط تركز على السعر والتوفر والقرار الأساسي.','Cleaner product cards focused on price, availability and the primary action.')}</p></div><a href="${url('collection.html')}">${t('عرض المتجر','Open shop')} →</a></div>${grid(featured)}</div></section><section class="gr16-section"><div class="gr16-container"><div class="gr20-authority"><div><span class="gr16-kicker">FARM & B2B</span><h2>${t('للطلبات الكبيرة، فيه مسار أقصر.','For larger orders, there is a shorter path.')}</h2><p>${t('الطلب السريع وقوائم المزرعة وطلب عرض السعر موجودين بعيد عن رحلة التسوق العادية عشان كل عميل ياخد المسار المناسب.','Quick Order, Farm Lists and Request Quote live outside the standard retail flow so every customer gets the right path.')}</p></div><div class="gr20-authority-actions"><a class="gr16-btn gr16-btn--gold" href="${url('quick-order.html')}">${t('طلب سريع','Quick order')}</a><a class="gr16-btn gr18-dark-outline" href="${url('wholesale.html')}">${t('طلب عرض سعر','Request quote')}</a></div></div></div></section>${sale.length?`<section class="gr16-section"><div class="gr16-container"><div class="gr16-head gr18-head"><div><span class="gr16-kicker">SELECTED OFFERS</span><h2>${t('عروض موجودة فعليًا داخل الكتالوج','Offers currently represented in the catalog')}</h2></div><a href="${url('offers.html')}">${t('كل العروض','All offers')} →</a></div>${grid(sale)}</div></section>`:''}<section class="gr16-section"><div class="gr16-container"><div class="gr16-head gr18-head"><div><span class="gr16-kicker">TRUST CENTER</span><h2>${t('الثقة جزء من رحلة الشراء','Trust is part of the buying journey')}</h2></div><a href="${url('trust.html')}">${t('مركز الثقة','Trust center')} →</a></div><div class="gr20-trust-grid">${(GR20.trust||[]).map(x=>`<article class="gr20-trust-card"><i>${x.icon}</i><h3>${esc(t(x.ar,x.en))}</h3><p>${esc(t(x.copy_ar,x.copy_en))}</p></article>`).join('')}</div></div></section><section class="gr16-section"><div class="gr16-container gr20-brand-landing"><div class="gr20-brand-emblem"><img src="assets/golden-roots-logo.webp" alt="GOLDEN ROOTS"></div><div class="gr20-brand-copy"><span class="gr16-kicker">BRAND AUTHORITY</span><h2>${t('GOLDEN ROOTS مش مجرد Grid منتجات.','GOLDEN ROOTS is more than a product grid.')}</h2><p>${t('الهوية، الكتالوج، الطلبات، العروض وخدمة المزارع متجمعة داخل بنية واحدة تخلي الشركة تظهر كعلامة تجارية متماسكة.','Identity, catalog, ordering, offers and farm service are combined into one structure that presents the company as a coherent brand.')}</p><a class="gr16-btn gr16-btn--outline" href="${url('brand.html',{brand:'GOLDEN ROOTS'})}">${t('صفحة العلامة التجارية','Brand page')}</a></div></div></section>${recentRows.length?`<section class="gr16-section gr18-recent"><div class="gr16-container"><div class="gr16-head gr18-head"><div><span class="gr16-kicker">RECENTLY VIEWED</span><h2>${t('كمّل من حيث وقفت','Continue where you left off')}</h2></div></div>${grid(recentRows)}</div></section>`:''}`}
function collectionsPage(){return pageHero('CATALOG',t('الأقسام الزراعية','Agricultural Categories'),t('ستة مسارات واضحة للوصول للمنتجات بسرعة.','Six clear paths to the products you need.'))+`<section class="gr16-section"><div class="gr16-container gr17-collections-grid">${Object.entries(C).map(([k,c])=>`<article class="gr17-cat-panel"><a href="${url('collection.html',{cat:k})}"><img src="${c.img}" alt="${esc(t(c.ar,c.en))}"><h2>${esc(t(c.ar,c.en))}</h2></a><nav>${Object.entries(c.subs||{}).map(([sk,v])=>`<a href="${url('collection.html',{cat:k,sub:sk})}">${esc(t(v[0],v[1]))}</a>`).join('')}</nav></article>`).join('')}</div></section>`}
function filterProducts(){let rows=[...P];const cat=params.get('cat')||'',sub=params.get('sub')||'',brand=params.get('brand')||'',stock=params.get('stock')||'',q=params.get('q')||'',min=+params.get('min')||0,max=+params.get('max')||Infinity;if(cat)rows=rows.filter(p=>p.cat===cat);if(sub)rows=rows.filter(p=>p.sub===sub);if(brand)rows=rows.filter(p=>p.brand===brand);if(stock==='in')rows=rows.filter(p=>p.stock>0);if(stock==='low')rows=rows.filter(p=>p.stock>0&&p.stock<10);if(stock==='out')rows=rows.filter(p=>p.stock<=0);if(q)rows=searchProducts(q).filter(p=>rows.includes(p));rows=rows.filter(p=>p.price>=min&&p.price<=max);const sort=params.get('sort')||'featured';if(sort==='price-asc')rows.sort((a,b)=>a.price-b.price);if(sort==='price-desc')rows.sort((a,b)=>b.price-a.price);if(sort==='name')rows.sort((a,b)=>String(a[isAR?'ar':'en']).localeCompare(String(b[isAR?'ar':'en'])));if(sort==='stock')rows.sort((a,b)=>b.stock-a.stock);if(sort==='sale')rows.sort((a,b)=>(b.old?1:0)-(a.old?1:0));return rows}
function collectionPage(){const rows=filterProducts(),cat=params.get('cat')||'',sub=params.get('sub')||'',title=sub&&cat?subName(cat,sub):cat?catName(cat):t('كل المنتجات','All Products'),cc=GR20.categories?.[cat],brands=[...new Set(P.map(p=>p.brand))];const intro=cat&&cc?`<section class="gr16-container"><div class="gr20-category-hero"><div class="gr20-category-hero__copy"><span class="gr16-kicker">${esc(cc.kicker||'CATEGORY')}</span><h1>${esc(sub?subName(cat,sub):t(cc.ar,cc.en))}</h1><p>${esc(t(cc.copy_ar,cc.copy_en))}</p><div class="gr20-category-points">${(isAR?cc.points_ar:cc.points_en).map(x=>`<span>${esc(x)}</span>`).join('')}</div></div><div class="gr20-category-hero__media"><img src="${C[cat]?.img||'assets/golden-roots-hero.webp'}" alt="${esc(title)}"></div></div><nav class="gr20-subnav"><a class="${!sub?'is-active':''}" href="${url('collection.html',{cat})}">${t('كل القسم','All category')}</a>${Object.entries(C[cat]?.subs||{}).map(([sk,v])=>`<a class="${sub===sk?'is-active':''}" href="${url('collection.html',{cat,sub:sk})}">${esc(t(v[0],v[1]))}</a>`).join('')}</nav></section>`:pageHero('SHOP',title,t(`${rows.length} منتج متاح للتصفح`,`${rows.length} products available to browse`));return intro+`<section class="gr16-section"><div class="gr16-container"><div class="gr16-head gr18-head"><div><span class="gr16-kicker">CATALOG</span><h2>${esc(title)}</h2><p>${t(`${rows.length} نتيجة بعد الفلاتر الحالية`,`${rows.length} results with the current filters`)}</p></div></div><form class="gr17-filterbar gr19-filterbar" data-filter-form><input class="gr19-filter-search" type="search" name="q" value="${esc(params.get('q')||'')}" placeholder="${t('ابحث داخل النتائج','Search within results')}" aria-label="${t('بحث داخل المنتجات','Search products')}">${sub&&cat?`<input type="hidden" name="sub" value="${esc(sub)}">`:''}<select name="cat" aria-label="${t('القسم','Category')}"><option value="">${t('كل الأقسام','All categories')}</option>${Object.keys(C).map(k=>`<option value="${k}" ${cat===k?'selected':''}>${esc(catName(k))}</option>`).join('')}</select><select name="stock"><option value="">${t('كل حالات التوفر','All availability')}</option><option value="in" ${params.get('stock')==='in'?'selected':''}>${t('متوفر','In stock')}</option><option value="low" ${params.get('stock')==='low'?'selected':''}>${t('كمية محدودة','Low stock')}</option><option value="out" ${params.get('stock')==='out'?'selected':''}>${t('غير متوفر','Out of stock')}</option></select><select name="brand"><option value="">${t('كل البراندات','All brands')}</option>${brands.map(b=>`<option ${params.get('brand')===b?'selected':''}>${esc(b)}</option>`).join('')}</select><div class="gr17-price-filter"><input type="number" name="min" min="0" value="${params.get('min')||''}" placeholder="${t('من','Min')}"><span>—</span><input type="number" name="max" min="0" value="${params.get('max')||''}" placeholder="${t('إلى','Max')}"></div><select name="sort"><option value="featured">${t('مميز','Featured')}</option><option value="price-asc" ${params.get('sort')==='price-asc'?'selected':''}>${t('السعر: الأقل','Price: low')}</option><option value="price-desc" ${params.get('sort')==='price-desc'?'selected':''}>${t('السعر: الأعلى','Price: high')}</option><option value="stock" ${params.get('sort')==='stock'?'selected':''}>${t('الأكثر توفرًا','Most available')}</option><option value="sale" ${params.get('sort')==='sale'?'selected':''}>${t('العروض أولًا','Sales first')}</option></select><button class="gr16-btn gr16-btn--primary">${t('تطبيق','Apply')}</button><a class="gr16-btn gr16-btn--outline" href="${url('collection.html',cat?{cat}: {})}">${t('مسح الفلاتر','Reset filters')}</a></form>${rows.length?grid(rows):zeroResults(params.get('q')||title)}</div></section>${cat?`<section class="gr16-section"><div class="gr16-container"><div class="gr20-authority"><div><span class="gr16-kicker">NEED VOLUME?</span><h2>${t('لو الطلب للمزرعة أو المشروع، اختصر الخطوات.','If this is for a farm or project, shorten the process.')}</h2><p>${t('استخدم الطلب السريع للكميات أو أرسل طلب عرض سعر بدل إضافة كل منتج بالطريقة التقليدية.','Use Quick Order for quantities or Request Quote instead of adding every item through the standard retail flow.')}</p></div><div class="gr20-authority-actions"><a class="gr16-btn gr16-btn--gold" href="${url('quick-order.html')}">${t('طلب سريع','Quick order')}</a><a class="gr16-btn gr18-dark-outline" href="${url('wholesale.html')}">${t('عرض سعر','Request quote')}</a></div></div></div></section>`:''}`}
function zeroResults(q){const alts=P.filter(p=>p.stock>0).slice(0,4);return `<div class="gr16-empty gr17-zero"><h2>${t('مفيش نتيجة مطابقة بالضبط','No exact match found')}</h2><p>${t('جرّب كلمة أقصر أو تصفح المنتجات المقترحة.','Try a shorter term or browse these suggestions.')}</p><a class="gr16-btn gr16-btn--primary" href="${url('collection.html')}">${t('عرض كل المنتجات','View all products')}</a></div><div class="gr17-zero-suggestions">${grid(alts)}</div>`}
function productPage(){const id=params.get('id'),p=product(id);if(!p)return notFound();recent=[id,...recent.filter(x=>x!==id)].slice(0,12);set(K.recent,recent);const vi=clamp(Math.floor(+params.get('variant')||0),0,Math.max(0,(p.variants?.length||1)-1)),v=variantInfo(p,vi),specs=isAR?p.specs_ar:p.specs_en,gallery=[p.img,C[p.cat]?.img,'assets/golden-roots-hero.webp'].filter(Boolean),specRows=Object.entries(specs||{}),crossCats=GR20.crossSell?.[p.cat]||[],cross=P.filter(x=>x.id!==p.id&&x.stock>0&&crossCats.includes(x.cat)).slice(0,4),same=P.filter(x=>x.id!==p.id&&x.stock>0&&x.cat===p.cat).slice(0,4);return `<section class="gr16-section gr18-product-section"><div class="gr16-container"><nav class="gr16-breadcrumb"><a href="${url('index.html')}">${t('الرئيسية','Home')}</a><span>›</span><a href="${url('collection.html',{cat:p.cat})}">${catName(p.cat)}</a><span>›</span><span>${esc(p[isAR?'ar':'en'])}</span></nav><div class="gr16-product-layout gr18-product-layout"><div class="gr16-gallery gr18-gallery"><button class="gr17-main-image gr18-main-image" data-gallery-main data-zoom-src="${gallery[0]}"><img class="gr16-main-image" src="${gallery[0]}" alt="${esc(p[isAR?'ar':'en'])}"><span class="gr18-zoom-hint">⌕ ${t('تكبير الصورة','Zoom image')}</span></button><div class="gr16-thumbs gr18-thumbs">${gallery.map((im,i)=>`<button class="gr16-thumb ${i===0?'is-active':''}" data-thumb="${im}" aria-label="${t('صورة المنتج','Product image')} ${i+1}"><img src="${im}" alt=""></button>`).join('')}</div></div><div class="gr16-product-copy gr18-purchase-panel"><div class="gr18-product-head"><span class="gr16-kicker">${esc(t(p.type_ar,p.type_en))}</span><div class="gr18-product-mini-actions"><button data-wish="${p.id}" aria-label="${t('المفضلة','Wishlist')}">${icon('heart')}</button><button data-compare="${p.id}" aria-label="${t('مقارنة','Compare')}">⇄</button></div></div><h1>${esc(p[isAR?'ar':'en'])}</h1><div class="gr16-product-meta"><a href="${url('brand.html',{brand:p.brand})}">${esc(p.brand)}</a><span>SKU: ${esc(p.sku)}</span><span class="gr16-stock ${p.stock<=0?'sold':''}">${p.stock<=0?t('غير متوفر حاليًا','Currently unavailable'):p.stock<10?t(`متبقي ${p.stock} فقط`,`Only ${p.stock} left`):t('متوفر','In stock')}</span></div><div class="gr16-product-price gr18-product-price"><strong data-product-price>${money(v.price)}</strong>${p.old?`<del>${money(p.old)}</del>`:''}</div>${specRows.length?`<div class="gr20-value-row">${specRows.slice(0,3).map(([k,val])=>`<div><small>${esc(k)}</small><b>${esc(val)}</b></div>`).join('')}</div>`:''}${p.variants?.length?`<label class="gr17-field gr18-field">${t('اختر العبوة / الخيار','Choose pack / option')}<select data-variant>${p.variants.map((x,i)=>`<option value="${i}" ${i===vi?'selected':''}>${esc(t(x[0],x[1]))} — ${money(x[2])}</option>`).join('')}</select></label>`:''}<div class="gr16-buyrow gr18-buyrow"><div class="gr16-qty"><button data-qminus aria-label="${t('تقليل','Decrease')}">−</button><input data-qty type="number" min="1" max="${Math.max(1,p.stock)}" value="1" aria-label="${t('الكمية','Quantity')}"><button data-qplus aria-label="${t('زيادة','Increase')}">+</button></div><button class="gr16-btn gr16-btn--primary" data-product-add="${p.id}" ${p.stock<=0?'disabled':''}>${p.stock>0?t('أضف للسلة','Add to cart'):t('غير متوفر','Unavailable')}</button></div><div class="gr20-buy-confidence"><span>${t('سعر واضح قبل الطلب','Clear price before ordering')}</span><span>${t('حالة توفر ظاهرة','Availability visible')}</span><span>${t('حفظ ومقارنة','Save & compare')}</span></div><div class="gr18-secondary-actions"><button data-list-dialog="${p.id}">＋ ${t('إضافة لقائمة مزرعة','Add to farm list')}</button><a href="${url('quick-order.html')}">${t('طلب كميات','Volume order')} ↗</a></div><div class="gr20-share-row"><button data-share-product="${p.id}">${t('مشاركة المنتج','Share product')}</button><a href="${url('contact.html')}">${t('استفسار','Ask us')}</a></div>${p.cat==='pesticides'?`<div class="gr20-safety">${t('استخدم منتجات حماية المحاصيل وفق ملصق المنتج والتعليمات المعتمدة، ولا تعتمد على بطاقة المتجر وحدها لاتخاذ قرار الاستخدام.','Use crop-protection products according to the product label and approved instructions; do not rely on the storefront card alone for use decisions.')}</div>`:''}${specRows.length?`<details class="gr18-spec-details" open><summary>${t('مواصفات المنتج','Product specifications')}</summary><div class="gr16-specs">${specRows.map(([k,val])=>`<div class="gr16-spec"><span>${esc(k)}</span><b>${esc(val)}</b></div>`).join('')}</div></details>`:''}</div></div></div></section><div class="gr18-mobile-buy"><div><small>${esc(p[isAR?'ar':'en'])}</small><strong data-product-price-mobile>${money(v.price)}</strong></div><button class="gr16-btn gr16-btn--primary" data-product-add="${p.id}" ${p.stock<=0?'disabled':''}>${p.stock>0?t('أضف للسلة','Add to cart'):t('غير متوفر','Unavailable')}</button></div><section class="gr16-section"><div class="gr16-container gr20-product-story"><div><span class="gr16-kicker">PRODUCT INFO</span><h2>${t('المعلومة الأساسية في مكان واحد','Core information in one place')}</h2><p>${t('اسم المنتج، الاختيارات، السعر، التوفر والمواصفات تظهر في نفس لوحة الشراء بدون أقسام تسويقية زائدة.','Product name, options, price, availability and specifications live in the same purchase panel without unnecessary marketing blocks.')}</p></div><div><span class="gr16-kicker">ORDER PATHS</span><h2>${t('شراء عادي أو كميات','Retail or volume ordering')}</h2><p>${t('أضف للسلة للطلب العادي، أو انتقل للطلب السريع وطلب عرض السعر إذا كانت الكمية أكبر.','Add to cart for standard orders, or move to Quick Order and Request Quote for larger quantities.')}</p></div></div></section>${cross.length?`<section class="gr16-section"><div class="gr16-container"><div class="gr16-head gr18-head"><div><span class="gr16-kicker">COMPLETE THE ORDER</span><h2>${t('احتياجات مكملة من أقسام مرتبطة','Complementary needs from related categories')}</h2><p>${t('اقتراحات مبنية على علاقة الأقسام، مش Upsell عشوائي.','Suggestions are based on category relationships, not random upsells.')}</p></div></div>${grid(cross)}</div></section>`:''}${same.length?`<section class="gr16-section gr18-related"><div class="gr16-container"><div class="gr16-head gr18-head"><div><span class="gr16-kicker">MORE IN CATEGORY</span><h2>${t('اختيارات أخرى من نفس القسم','More from this category')}</h2></div></div>${grid(same)}</div></section>`:''}`}
function offersPage(){const rows=P.filter(p=>p.old&&p.old>p.price&&p.stock>0),campaigns=Object.entries(GR20.campaigns||{});return `<section class="gr16-container"><div class="gr20-offer-hero"><div><span class="gr16-kicker">OFFERS HUB</span><h1>${t('العروض والحملات في مكان واحد','Offers and campaigns in one place')}</h1><p>${t('صفحة تجارية تجمع المنتجات التي يظهر عليها سعر مخفض ومسارات الحملات بدون عدادات وهمية أو استعجال مصطنع.','A commercial hub for reduced-price catalog items and campaign paths, without fake countdowns or artificial urgency.')}</p></div><div class="gr20-offer-stat">${rows.length}<small>${t('منتجات عليها سعر سابق','items with a previous price')}</small></div></div></section><section class="gr16-section"><div class="gr16-container"><div class="gr20-campaign-grid">${campaigns.map(([id,c])=>`<article class="gr20-campaign-card"><div><small>${esc(c.kicker||'CAMPAIGN')}</small><h3>${esc(t(c.ar,c.en))}</h3><p>${esc(t(c.copy_ar,c.copy_en))}</p></div><a href="${id==='selected-offers'?'#offer-products':url('campaign.html',{campaign:id})}">${t('فتح الحملة','Open campaign')} →</a></article>`).join('')}</div></div></section><section class="gr16-section" id="offer-products"><div class="gr16-container"><div class="gr16-head gr18-head"><div><span class="gr16-kicker">REDUCED PRICE</span><h2>${t('المنتجات ذات السعر المخفض','Products with a reduced price')}</h2></div></div>${rows.length?grid(rows):zeroResults('sale')}</div></section>`}
function saveSearch(q){if(!q.trim())return;let h=get(K.searches,[]);h=[q.trim(),...h.filter(x=>norm(x)!==norm(q))].slice(0,6);set(K.searches,h)}
function searchPage(){const q=params.get('q')||'',rows=searchProducts(q);saveSearch(q);return pageHero('SEARCH',t('البحث','Search'),q?t(`نتائج البحث عن «${esc(q)}»`,`Results for “${esc(q)}”`):t('ابحث بالاسم أو SKU أو نوع المنتج.','Search by name, SKU or product type.'))+`<section class="gr16-section"><div class="gr16-container"><form class="gr17-search-page-form"><input name="q" value="${esc(q)}" placeholder="${t('مثال: سماد 20-20-20 أو GR-SE','Example: 20-20-20 or GR-SE')}"><button class="gr16-btn gr16-btn--primary">${t('بحث','Search')}</button></form>${q&&rows.length?grid(rows):q?zeroResults(q):`<div class="gr17-popular-searches"><h2>${t('ابدأ بكلمة','Start with a term')}</h2>${['بذور','سماد','مبيد','ري','tools','NPK'].map(x=>`<a href="${url('search.html',{q:x})}">${x}</a>`).join('')}</div>`}</div></section>`}
function cartPage(){const rows=cart.map(lineData).filter(Boolean),cats=[...new Set(rows.map(x=>x.p.cat))],ids=new Set(rows.map(x=>x.p.id)),relCats=[...new Set(cats.flatMap(c=>GR20.crossSell?.[c]||[]))],upsell=P.filter(p=>p.stock>0&&!ids.has(p.id)&&relCats.includes(p.cat)).slice(0,2);return pageHero('CART',t('سلة التسوق','Shopping Cart'),t('راجع المنتجات والكميات قبل إكمال الطلب.','Review products and quantities before checkout.'))+`<section class="gr16-section"><div class="gr16-container gr16-cart-layout"><div data-cart-page>${rows.length?rows.map((d,i)=>`<article class="gr16-cart-line gr17-cart-page-line" data-page-line="${i}"><img src="${d.p.img}" alt=""><div><a href="${url('product.html',{id:d.p.id})}"><strong>${esc(d.p[isAR?'ar':'en'])}</strong></a><small>${esc(d.v.label)} · ${esc(d.p.sku)}</small><div class="gr16-line-actions"><button data-page-dec aria-label="${t('تقليل الكمية','Decrease quantity')}">−</button><span>${d.qty}</span><button data-page-inc aria-label="${t('زيادة الكمية','Increase quantity')}">+</button><button class="gr16-linkbtn" data-page-save="${d.p.id}">${t('حفظ','Save')}</button><button class="gr16-linkbtn" data-page-remove>${t('حذف','Remove')}</button></div></div><b>${money(d.price*d.qty)}</b></article>`).join(''):`<div class="gr16-empty"><h2>${t('السلة فارغة','Your cart is empty')}</h2><a class="gr16-btn gr16-btn--primary" href="${url('collection.html')}">${t('ابدأ التسوق','Start shopping')}</a></div>`}${upsell.length?`<div class="gr20-cart-upsell"><h3>${t('أكمل الطلب باحتياجات مرتبطة','Complete the order with related needs')}</h3><div class="gr20-upsell-row">${upsell.map(p=>`<article class="gr20-upsell"><img src="${p.img}" alt=""><div><strong>${esc(p[isAR?'ar':'en'])}</strong><small>${money(p.price)}</small></div><button class="gr16-btn gr16-btn--outline" data-add="${p.id}">＋</button></article>`).join('')}</div></div>`:''}</div><aside class="gr16-summary"><h3>${t('ملخص الطلب','Order summary')}</h3><div class="gr16-summary-row"><span>${t('المجموع الفرعي','Subtotal')}</span><b>${money(subtotal())}</b></div>${discount()?`<div class="gr16-summary-row"><span>${t('الخصم','Discount')}</span><b>−${money(discount())}</b></div>`:''}<form class="gr17-coupon" data-coupon-form><input name="coupon" value="${esc(coupon)}" placeholder="${t('رمز الخصم','Discount code')}"><button>${t('تطبيق','Apply')}</button></form><div class="gr16-summary-row total"><span>${t('الإجمالي','Total')}</span><strong>${money(total())}</strong></div><a class="gr16-btn gr16-btn--primary ${rows.length?'':'is-disabled'}" href="${rows.length?url('checkout.html'):'#'}">${t('إكمال الطلب','Checkout')}</a><button class="gr16-btn gr16-btn--outline" data-save-cart ${rows.length?'':'disabled'}>${t('حفظ السلة للرجوع لها','Save cart for later')}</button><a class="gr16-btn gr16-btn--outline" href="${url('trust.html')}">${t('الشحن والاسترجاع والثقة','Shipping, returns & trust')}</a></aside></div></section>`}
function checkoutPage(){if(!cart.length)return pageHero('CHECKOUT',t('إتمام الطلب','Checkout'))+`<section class="gr16-section"><div class="gr16-container gr16-empty"><h2>${t('السلة فارغة','Your cart is empty')}</h2><a class="gr16-btn gr16-btn--primary" href="${url('collection.html')}">${t('العودة للمتجر','Back to shop')}</a></div></section>`;const draft=get(K.draft,{});return `<div class="gr20-env-note">${t('الدفع الإلكتروني غير مفعل حاليًا — هذه الصفحة تعرض تجربة إتمام الطلب فقط.','Online payment is not enabled yet — this page demonstrates the checkout experience only.')}</div><section class="gr17-checkout-head gr18-checkout-head"><div class="gr16-container"><a href="${url('index.html')}"><img src="assets/golden-roots-logo.webp" alt="GOLDEN ROOTS"></a><span>${t('إتمام الطلب','Checkout')}</span></div></section><section class="gr16-section"><div class="gr16-container gr16-checkout-layout"><div><div class="gr20-checkout-confidence"><span>${t('بيانات واضحة','Clear details')}</span><span>${t('عنوان قبل الدفع','Address before payment')}</span><span>${t('لا يتم تحصيل مبلغ الآن','No charge is collected now')}</span></div><div class="gr17-stepper"><span class="is-active" data-step-dot="1">1 <b>${t('البيانات','Details')}</b></span><span data-step-dot="2">2 <b>${t('العنوان','Address')}</b></span><span data-step-dot="3">3 <b>${t('الدفع','Payment')}</b></span></div><form class="gr16-panel gr16-form gr17-checkout-form" data-checkout-form><section data-checkout-step="1"><h2>${t('بيانات التواصل','Contact details')}</h2><div class="gr16-form-grid"><label>${t('الاسم الكامل','Full name')}<input name="name" autocomplete="name" required minlength="2" value="${esc(draft.name||'')}"></label><label>${t('رقم الهاتف','Phone')}<input name="phone" autocomplete="tel" required inputmode="tel" minlength="7" value="${esc(draft.phone||'')}"></label><label>${t('البريد الإلكتروني','Email')}<input name="email" autocomplete="email" type="email" value="${esc(draft.email||'')}"></label></div><button type="button" class="gr16-btn gr16-btn--primary" data-next-step="2">${t('التالي: العنوان','Next: address')}</button></section><section data-checkout-step="2" hidden><h2>${t('عنوان التوصيل','Delivery address')}</h2><div class="gr16-form-grid"><label>${t('الإمارة','Emirate')}<select name="emirate" autocomplete="address-level1" required><option value="">${t('اختر الإمارة','Select emirate')}</option>${['Dubai','Abu Dhabi','Sharjah','Ajman','Umm Al Quwain','Ras Al Khaimah','Fujairah'].map(x=>`<option ${draft.emirate===x?'selected':''}>${x}</option>`).join('')}</select></label><label>${t('المدينة / المنطقة','City / Area')}<input name="area" autocomplete="address-level2" required value="${esc(draft.area||'')}"></label><label class="gr17-span-2">${t('العنوان بالتفصيل','Full address')}<input name="address" autocomplete="street-address" required value="${esc(draft.address||'')}"></label><label class="gr17-span-2">${t('ملاحظات التوصيل','Delivery notes')}<textarea name="notes">${esc(draft.notes||'')}</textarea></label></div><div class="gr17-step-actions"><button type="button" class="gr16-btn gr16-btn--outline" data-prev-step="1">${t('السابق','Back')}</button><button type="button" class="gr16-btn gr16-btn--primary" data-next-step="3">${t('التالي: الدفع','Next: payment')}</button></div></section><section data-checkout-step="3" hidden><h2>${t('طريقة الدفع','Payment method')}</h2><div class="gr16-paymethods"><label class="gr16-paymethod"><input type="radio" name="payment" value="card" checked><div><b>${t('بطاقة بنكية','Bank card')}</b><span>${t('واجهة فقط الآن. حقول الدفع الحقيقية تظهر عند ربط مزود دفع معتمد.','Interface only for now. Real payment fields appear when an approved provider is connected.')}</span></div></label><label class="gr16-paymethod"><input type="radio" name="payment" value="cod"><div><b>${t('الدفع عند الاستلام','Cash on delivery')}</b><span>${t('يظهر كخيار تشغيلي فقط إذا تم اعتماده لاحقًا.','Shown as an operational option only if enabled later.')}</span></div></label></div><div class="gr17-step-actions"><button type="button" class="gr16-btn gr16-btn--outline" data-prev-step="2">${t('السابق','Back')}</button><button class="gr16-btn gr16-btn--primary" type="submit">${t('إنشاء طلب تجريبي','Create test order')}</button></div></section></form></div><aside class="gr16-summary"><h3>${t('طلبك','Your order')}</h3>${cart.map(lineData).filter(Boolean).map(d=>`<div class="gr17-check-line"><span>${esc(d.p[isAR?'ar':'en'])} × ${d.qty}</span><b>${money(d.price*d.qty)}</b></div>`).join('')}<div class="gr16-summary-row total"><span>${t('الإجمالي','Total')}</span><strong>${money(total())}</strong></div><a href="${url('trust.html')}">${t('معلومات الشحن والاسترجاع والثقة','Shipping, returns & trust information')} →</a></aside></div></section>`}
function orderConfirmationPage(){const oid=params.get('order');const o=orders.find(x=>x.id===oid)||orders[0];if(!o)return pageHero('ORDER',t('لا يوجد طلب محفوظ','No saved order'))+`<section class="gr16-section"><div class="gr16-container gr16-empty"><a class="gr16-btn gr16-btn--primary" href="${url('index.html')}">${t('الرئيسية','Home')}</a></div></section>`;return `<section class="gr16-section"><div class="gr16-container gr17-confirm"><div class="gr17-success-mark">✓</div><span class="gr16-kicker">${esc(o.id)}</span><h1>${t('تم إنشاء الطلب داخل وضع التجربة','Order created in test mode')}</h1><p>${t('تم حفظ الطلب محليًا على هذا الجهاز فقط، ولن يتم إرساله إلى الشركة أو تحصيل أي مبلغ.','This order is saved locally on this device only. It is not sent to the company and no payment is collected.')}</p><div class="gr16-panel"><div class="gr16-summary-row"><span>${t('الاسم','Name')}</span><b>${esc(o.customer.name)}</b></div><div class="gr16-summary-row"><span>${t('الإمارة','Emirate')}</span><b>${esc(o.customer.emirate)}</b></div><div class="gr16-summary-row"><span>${t('الإجمالي','Total')}</span><b>${money(o.total)}</b></div></div><div class="gr17-step-actions"><a class="gr16-btn gr16-btn--primary" href="${url('account.html')}">${t('عرض طلباتي','View my orders')}</a><a class="gr16-btn gr16-btn--outline" href="${url('collection.html')}">${t('متابعة التسوق','Continue shopping')}</a></div></div></section>`}
function wishlistPage(){const rows=wish.map(product).filter(Boolean);return pageHero('WISHLIST',t('المفضلة','Wishlist'),t('منتجات حفظتها للرجوع إليها بسرعة.','Products you saved for quick access.'))+`<section class="gr16-section"><div class="gr16-container">${rows.length?grid(rows):`<div class="gr16-empty"><h2>${t('المفضلة فارغة','Your wishlist is empty')}</h2><a class="gr16-btn gr16-btn--primary" href="${url('collection.html')}">${t('تصفح المنتجات','Browse products')}</a></div>`}</div></section>`}
function comparePage(){const rows=compare.map(product).filter(Boolean);return pageHero('COMPARE',t('مقارنة المنتجات','Compare Products'),t('قارن حتى 4 منتجات جنبًا إلى جنب.','Compare up to 4 products side by side.'))+`<section class="gr16-section"><div class="gr16-container">${rows.length?`<div class="gr16-table-wrap"><table class="gr16-table gr17-compare-table"><thead><tr><th>${t('المعيار','Attribute')}</th>${rows.map(p=>`<th><img src="${p.img}" alt=""><a href="${url('product.html',{id:p.id})}">${esc(p[isAR?'ar':'en'])}</a><button data-compare="${p.id}" aria-label="${t('إزالة من المقارنة','Remove from comparison')}">×</button></th>`).join('')}</tr></thead><tbody><tr><td>${t('السعر','Price')}</td>${rows.map(p=>`<td>${money(p.price)}</td>`).join('')}</tr><tr><td>SKU</td>${rows.map(p=>`<td>${esc(p.sku)}</td>`).join('')}</tr><tr><td>${t('التوفر','Availability')}</td>${rows.map(p=>`<td>${p.stock>0?t('متوفر','In stock'):t('غير متوفر','Out of stock')}</td>`).join('')}</tr><tr><td>${t('النوع','Type')}</td>${rows.map(p=>`<td>${esc(t(p.type_ar,p.type_en))}</td>`).join('')}</tr></tbody></table></div>`:`<div class="gr16-empty"><h2>${t('لم تختر منتجات للمقارنة','No products selected')}</h2><a class="gr16-btn gr16-btn--primary" href="${url('collection.html')}">${t('اختيار منتجات','Choose products')}</a></div>`}</div></section>`}
function quickOrderPage(){return pageHero('QUICK ORDER',t('الطلب السريع للمزارع','Farm Quick Order'),t('حدد الكمية لكل منتج ثم أضف الطلب كله للسلة مرة واحدة.','Set quantities and add the whole order to cart in one action.'))+`<section class="gr16-section"><div class="gr16-container"><div class="gr16-panel"><input class="gr16-filter-input" data-qofilter placeholder="${t('ابحث بالاسم أو SKU...','Search by name or SKU...')}"><div class="gr16-table-wrap"><table class="gr16-table"><thead><tr><th>${t('المنتج','Product')}</th><th>SKU</th><th>${t('السعر','Price')}</th><th>${t('التوفر','Stock')}</th><th>${t('الكمية','Qty')}</th></tr></thead><tbody>${P.map(p=>`<tr data-qorow data-search="${esc(norm(p.ar+' '+p.en+' '+p.sku))}"><td><a href="${url('product.html',{id:p.id})}">${esc(p[isAR?'ar':'en'])}</a></td><td>${esc(p.sku)}</td><td>${money(p.price)}</td><td>${p.stock}</td><td><input data-qoqty="${p.id}" type="number" min="0" max="${Math.max(0,p.stock)}" value="0" aria-label="${t('كمية المنتج','Product quantity')}" ${p.stock<=0?'disabled':''}></td></tr>`).join('')}</tbody></table></div><button class="gr16-btn gr16-btn--primary" data-qoadd>${t('إضافة الكميات المحددة للسلة','Add selected quantities to cart')}</button></div></div></section>`}
function savedListsPage(){const names=Object.keys(lists);return pageHero('FARM LISTS',t('قوائم المزرعة','Farm Lists'),t('احفظ مجموعات منتجات متكررة لاستخدامها مرة أخرى.','Save reusable groups of products for repeat purchasing.'))+`<section class="gr16-section"><div class="gr16-container"><div class="gr17-create-list"><input data-new-list placeholder="${t('اسم القائمة، مثال: طلب المزرعة الشهري','List name, e.g. Monthly farm order')}"><button class="gr16-btn gr16-btn--primary" data-create-list>${t('إنشاء قائمة','Create list')}</button></div>${names.length?`<div class="gr17-list-grid">${names.map(n=>`<article class="gr16-panel"><div class="gr16-head"><div><h2>${esc(n)}</h2><span>${lists[n].length} ${t('منتجات','products')}</span></div><button class="gr16-linkbtn" data-list-delete="${esc(n)}">${t('حذف','Delete')}</button></div><div class="gr17-mini-products">${lists[n].map(product).filter(Boolean).map(p=>`<a href="${url('product.html',{id:p.id})}"><img src="${p.img}" alt=""><span>${esc(p[isAR?'ar':'en'])}</span></a>`).join('')||`<p>${t('القائمة فارغة. أضف منتجات من صفحة المنتج.','This list is empty. Add products from a product page.')}</p>`}</div><button class="gr16-btn gr16-btn--outline" data-list-addall="${esc(n)}">${t('إضافة القائمة للسلة','Add list to cart')}</button></article>`).join('')}</div>`:`<div class="gr16-empty"><h2>${t('لسه مفيش قوائم محفوظة','No saved lists yet')}</h2><p>${t('أنشئ أول قائمة ثم أضف لها المنتجات من صفحات المنتجات.','Create your first list, then add products from product pages.')}</p></div>`}</div></section>`}
function brandsPage(){const brands=[...new Set(P.map(p=>p.brand))];return pageHero('BRANDS',t('العلامات التجارية','Brands'),t('كل علامة لها صفحة تجمع قصتها ومنتجاتها بدل فلتر صامت فقط.','Each brand gets a landing page that combines its story and products instead of a silent filter only.'))+`<section class="gr16-section"><div class="gr16-container gr17-brand-grid">${brands.map(b=>`<a class="gr16-panel" href="${url('brand.html',{brand:b})}"><span class="gr17-brand-mark">GR</span><h2>${esc(b)}</h2><p>${P.filter(p=>p.brand===b).length} ${t('منتج','products')}</p><b>${t('فتح صفحة البراند','Open brand page')} →</b></a>`).join('')}</div></section>`}
function accountPage(){const saved=get(K.savedCart,[]);return pageHero('ACCOUNT',t('حسابي','My Account'),t('كل اختياراتك وطلباتك المحفوظة في مكان واحد.','Your saved choices, lists and orders in one place.'))+`<section class="gr16-section"><div class="gr16-container"><div class="gr17-account-cards"><a class="gr16-panel" href="${url('wishlist.html')}"><b>${wish.length}</b><span>${t('في المفضلة','Wishlist items')}</span></a><a class="gr16-panel" href="${url('saved-lists.html')}"><b>${Object.keys(lists).length}</b><span>${t('قوائم مزرعة','Farm lists')}</span></a><div class="gr16-panel"><b>${orders.length}</b><span>${t('طلبات محفوظة','Saved orders')}</span></div><div class="gr16-panel"><b>${recent.length}</b><span>${t('شوهد مؤخرًا','Recently viewed')}</span></div></div><div class="gr16-head"><div><span class="gr16-kicker">${t('الطلبات','ORDERS')}</span><h2>${t('طلباتي الأخيرة','Recent orders')}</h2></div></div>${orders.length?`<div class="gr17-orders">${orders.map(o=>`<article class="gr16-panel"><div><b>${esc(o.id)}</b><span>${new Date(o.date).toLocaleDateString(isAR?'ar-AE':'en-AE')}</span></div><div><strong>${money(o.total)}</strong><span>${o.items.length} ${t('منتجات','items')}</span></div><div><a href="${url('order-confirmation.html',{order:o.id})}">${t('التفاصيل','Details')}</a><button data-reorder="${o.id}">${t('إعادة الطلب','Reorder')}</button></div></article>`).join('')}</div>`:`<div class="gr16-empty"><p>${t('لا توجد طلبات محفوظة على هذا الجهاز حتى الآن.','No orders are saved on this device yet.')}</p></div>`}${saved.length?`<section class="gr16-panel gr17-saved-cart"><div><h2>${t('سلة محفوظة','Saved cart')}</h2><p>${saved.length} ${t('أسطر منتجات محفوظة','saved cart lines')}</p></div><button class="gr16-btn gr16-btn--outline" data-restore-cart>${t('استعادة السلة','Restore cart')}</button></section>`:''}</div></section>`}
function wholesalePage(){return pageHero('FARM & B2B',t('طلبات المزارع والشركات','Farm & Business Orders'),t('مسار تجاري مستقل للطلبات الأكبر بدل خلطه مع رحلة العميل الفردي.','A dedicated commercial path for larger orders instead of mixing it into the retail journey.'))+`<section class="gr16-section"><div class="gr16-container"><div class="gr20-brand-proof"><div><b>${t('طلب سريع','Quick order')}</b><span>${t('أدخل الكميات مباشرة','Enter quantities directly')}</span></div><div><b>${t('قوائم محفوظة','Saved lists')}</b><span>${t('للطلبات المتكررة','For repeat orders')}</span></div><div><b>${t('عرض سعر','Request quote')}</b><span>${t('للمشروعات والكميات','For projects & volume')}</span></div><div><b>${t('كتالوج موحد','One catalog')}</b><span>${t('نفس المنتجات والـSKU','Same products & SKU')}</span></div></div></div></section><section class="gr16-section"><div class="gr16-container gr16-quote-grid"><div class="gr16-quote-aside"><span class="gr16-kicker">B2B</span><h2>${t('الطلب الكبير ما يحتاجش رحلة طويلة','A large order should not need a long journey')}</h2><p>${t('لو عندك قائمة واضحة استخدم الطلب السريع. لو الطلب مشروع أو يحتاج مراجعة، استخدم نموذج عرض السعر.','If you already know the list, use Quick Order. If it is a project or needs review, use Request Quote.')}</p><div class="gr20-commercial-actions"><a class="gr16-btn gr16-btn--outline" href="${url('quick-order.html')}">${t('فتح الطلب السريع','Open quick order')}</a><a class="gr16-btn gr16-btn--outline" href="${url('saved-lists.html')}">${t('القوائم المحفوظة','Saved lists')}</a></div></div><form class="gr16-panel gr16-form" data-quote-form><div class="gr16-form-grid"><label>${t('اسم الشركة / المزرعة','Company / farm name')}<input required name="company" autocomplete="organization"></label><label>${t('اسم المسؤول','Contact person')}<input required name="name" autocomplete="name"></label><label>${t('الهاتف','Phone')}<input required name="phone" autocomplete="tel"></label><label>${t('الإمارة','Emirate')}<input required name="emirate" autocomplete="address-level1"></label><label class="gr17-span-2">${t('تفاصيل المنتجات والكميات','Products and quantities')}<textarea required name="details"></textarea></label></div><button class="gr16-btn gr16-btn--primary">${t('حفظ طلب عرض السعر','Save quote request')}</button><small>${t('حاليًا يتم حفظ النموذج محليًا في نسخة الموقع المستقلة إلى أن يتم توصيل Backend حقيقي.','The standalone site currently saves this form locally until a real backend is connected.')}</small></form></div></section>`}
function staticPage(kind){const x=staticPages[kind];let body='';if(kind==='about')body=`<div class="gr20-brand-landing"><div class="gr20-brand-emblem"><img src="assets/golden-roots-logo.webp" alt="GOLDEN ROOTS"></div><div class="gr20-brand-copy"><span class="gr16-kicker">GOLDEN ROOTS</span><h1>${t('علامة زراعية بواجهة تجارية مرتبة.','An agricultural brand with a structured commercial experience.')}</h1><p>${t('جولدن روتس للزراعة ومستلزماتها تبني تجربة تجمع الكتالوج، العروض، طلبات الأفراد وطلبات المزارع والشركات في هوية واحدة واضحة.','Golden Roots Agriculture & Supplies brings catalog, offers, retail ordering and farm/business ordering into one clear brand experience.')}</p><div class="gr20-commercial-actions"><a class="gr16-btn gr16-btn--primary" href="${url('collection.html')}">${t('استكشف المتجر','Explore shop')}</a><a class="gr16-btn gr16-btn--outline" href="${url('contact.html')}">${t('تواصل معنا','Contact us')}</a></div></div></div>`;else if(kind==='contact')body=`<div class="gr16-quote-grid"><div class="gr16-quote-aside"><span class="gr16-kicker">CONTACT</span><h2>${t('اختار قناة التواصل المناسبة','Choose the right contact path')}</h2><p>${t('للاستفسارات العامة استخدم النموذج. للطلبات الكبيرة استخدم صفحة المزارع والشركات عشان التفاصيل تكون أوضح.','Use the form for general enquiries. For larger orders, use the Farm & B2B page so the request is structured properly.')}</p><a class="gr16-btn gr16-btn--outline" href="${url('wholesale.html')}">${t('طلبات المزارع والشركات','Farm & B2B')}</a></div><form class="gr16-panel gr16-form" data-contact-form><label>${t('الاسم','Name')}<input required name="name" autocomplete="name"></label><label>${t('الهاتف أو البريد','Phone or email')}<input required name="contact"></label><label>${t('الرسالة','Message')}<textarea required name="message"></textarea></label><button class="gr16-btn gr16-btn--primary">${t('حفظ الرسالة','Save message')}</button><small>${t('يتم حفظ النموذج محليًا في النسخة المستقلة حتى يتم توصيل خدمة إرسال حقيقية.','The standalone version stores this locally until a real submission service is connected.')}</small></form></div>`;else body=`<div class="gr16-policy"><h2>${t('معلومات الصفحة','Page information')}</h2><p>${t(x.copy_ar,x.copy_en)}</p><h2>${t('النص النهائي','Final wording')}</h2><p>${t('التصميم ومسار الصفحة جاهزان، ويجب اعتماد النص التشغيلي أو القانوني النهائي من الشركة قبل الإطلاق العام.','The page design and flow are ready; final operational or legal wording must be company-approved before public launch.')}</p></div>`;return pageHero(x.k,t(x.ar,x.en))+`<section class="gr16-section"><div class="gr16-container">${body}</div></section>`}
function faqPage(){const items=[[t('هل التوصيل متاح داخل كل الإمارات؟','Is delivery available across all emirates?'),t('الموقع مجهز لاختيار أي إمارة من الإمارات السبع، وتظهر رسوم ومدة التوصيل النهائية عند اعتماد التشغيل.','The site supports all seven emirates; final delivery rates and timing are shown when operations are enabled.')],[t('هل يمكن طلب كميات للمزرعة أو الشركة؟','Can farms or companies order in bulk?'),t('نعم، يوجد طلب سريع وقوائم مزرعة ومسار مستقل لطلب عرض سعر.','Yes. Quick Order, Farm Lists and Request Quote are available.')],[t('هل أقدر أحفظ المنتجات وأرجع لها؟','Can I save products for later?'),t('نعم، يمكنك استخدام المفضلة وقوائم المزرعة والسلة المحفوظة للرجوع لاختياراتك بسرعة.','Yes. Wishlist, Farm Lists and Saved Cart help you return to your selections quickly.')],[t('هل أقدر أبحث برقم SKU؟','Can I search by SKU?'),t('نعم، البحث يدعم اسم المنتج والقسم والكلمات العربية والإنجليزية ورقم SKU.','Yes. Search supports product names, categories, Arabic and English terms, and SKU.')]];return pageHero('FAQ',t('الأسئلة الشائعة','Frequently Asked Questions'))+`<section class="gr16-section"><div class="gr16-container gr16-accordion">${items.map(x=>`<details><summary>${x[0]}</summary><p>${x[1]}</p></details>`).join('')}</div></section>`}
function notFound(){return `<section class="gr18-404-wrap"><div class="gr18-404-art"><span>4</span><img src="assets/golden-roots-mark.webp" alt=""><span>4</span></div><div class="gr16-container gr18-404-copy"><span class="gr16-kicker">LOST IN THE FIELD?</span><h1>${t('الصفحة دي مش موجودة.','This page is not here.')}</h1><p>${t('ارجع للمتجر أو استخدم البحث عشان توصل للمنتج أو القسم اللي محتاجه.','Head back to the store or search for the product or category you need.')}</p><div class="gr17-step-actions"><button class="gr16-btn gr16-btn--outline" data-search-open>${t('بحث','Search')}</button><a class="gr16-btn gr16-btn--primary" href="${url('index.html')}">${t('الرئيسية','Home')}</a></div></div></section>`}
function renderSearch(q=''){const box=qs('[data-search-results]');if(!box)return;const rows=searchProducts(q).slice(0,8);box.innerHTML=rows.map(p=>`<a class="gr16-search-item" href="${url('product.html',{id:p.id})}"><img src="${p.img}" alt=""><div><strong>${esc(p[isAR?'ar':'en'])}</strong><small>${esc(p.sku)} · ${catName(p.cat)}</small></div><b>${money(p.price)}</b></a>`).join('')||`<div class="gr16-empty"><strong>${t('لا توجد نتائج','No results')}</strong><span>${t('جرّب كلمة أقصر مثل: سماد، بذور، ري.','Try a shorter term such as fertilizer, seeds or irrigation.')}</span></div>`;const h=qs('[data-search-history]'),hist=get(K.searches,[]);if(h)h.innerHTML=hist.length?`<span>${t('بحثت مؤخرًا:','Recent:')}</span>${hist.map(x=>`<a href="${url('search.html',{q:x})}">${esc(x)}</a>`).join('')}`:''}

function trustPage(){return `<section class="gr16-container"><div class="gr20-trust-hero"><span class="gr16-kicker">TRUST CENTER</span><h1>${t('كل ما يحتاجه العميل قبل ما يكمل الطلب','What customers need before they continue ordering')}</h1><p>${t('مركز واحد يجمع التوفر، مسارات الطلب، الشحن والاسترجاع وحالة الدفع الحالية بدون وعود تشغيلية غير معتمدة.','One place for availability, ordering paths, shipping, returns and current payment status without unapproved operational promises.')}</p><div class="gr20-trust-links"><a href="${url('shipping.html')}">${t('الشحن والتوصيل','Shipping')}</a><a href="${url('returns.html')}">${t('الاسترجاع','Returns')}</a><a href="${url('privacy.html')}">${t('الخصوصية','Privacy')}</a><a href="${url('contact.html')}">${t('التواصل','Contact')}</a></div></div></section><section class="gr16-section"><div class="gr16-container"><div class="gr20-trust-grid">${(GR20.trust||[]).map(x=>`<article class="gr20-trust-card"><i>${x.icon}</i><h3>${esc(t(x.ar,x.en))}</h3><p>${esc(t(x.copy_ar,x.copy_en))}</p></article>`).join('')}</div></div></section><section class="gr16-section"><div class="gr16-container gr16-accordion">${(GR20.trustFaq||[]).map(x=>`<details><summary>${esc(t(x[0],x[1]))}</summary><p>${esc(t(x[2],x[3]))}</p></details>`).join('')}</div></section>`}
function campaignPage(){const id=params.get('campaign')||GR20.activeCampaign,c=GR20.campaigns?.[id];if(!c)return notFound();let rows=[];if(id==='selected-offers')rows=P.filter(p=>p.old&&p.old>p.price&&p.stock>0);else rows=P.filter(p=>p.stock>0&&(c.cats||[]).includes(p.cat));return `<section class="gr16-container"><div class="gr20-offer-hero"><div><span class="gr16-kicker">${esc(c.kicker||'CAMPAIGN')}</span><h1>${esc(t(c.ar,c.en))}</h1><p>${esc(t(c.copy_ar,c.copy_en))}</p></div><div class="gr20-offer-stat">${rows.length}<small>${t('منتجات في المسار','products in this path')}</small></div></div></section><section class="gr16-section"><div class="gr16-container">${grid(rows.slice(0,12))}</div></section><section class="gr16-section"><div class="gr16-container"><div class="gr20-authority"><div><span class="gr16-kicker">NEXT STEP</span><h2>${t('تحتاج كميات أكبر؟','Need larger quantities?')}</h2><p>${t('استخدم الطلب السريع أو مسار عرض السعر بدل الاستمرار في إضافة كل قطعة بالطريقة التقليدية.','Use Quick Order or Request Quote instead of adding every item through the standard flow.')}</p></div><div class="gr20-authority-actions"><a class="gr16-btn gr16-btn--gold" href="${url('quick-order.html')}">${t('طلب سريع','Quick order')}</a><a class="gr16-btn gr18-dark-outline" href="${url('wholesale.html')}">${t('عرض سعر','Request quote')}</a></div></div></div></section>`}
